import{_ as d,C as h,o as r,c as A,a2 as E,b as n,w as t,a as o,E as s,a5 as i,j as l}from"./chunks/framework.DV9MvnYb.js";const c=JSON.parse('{"title":"ReMoE: Boosting Expert Reuse through Router Fine-Tuning in Memory-Constrained MoE LLM Inference","description":"ReMoE通过微调路由器使其倾向于重用近期专家，在不增加推理开销的前提下显著提升内存受限MoE推理的缓存效率和速度。","frontmatter":{"title":"ReMoE: Boosting Expert Reuse through Router Fine-Tuning in Memory-Constrained MoE LLM Inference","description":"ReMoE通过微调路由器使其倾向于重用近期专家，在不增加推理开销的前提下显著提升内存受限MoE推理的缓存效率和速度。","date":"2026-05-28","arxivId":"2605.27081","domain":"机器学习 · 人工智能 · 分布式系统","level":"进阶","tags":["混合专家模型","路由器微调","内存受限推理","专家重用","缓存优化"],"originalUrl":"https://arxiv.org/abs/2605.27081","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-05-28/2605.27081.md"},"headers":[],"relativePath":"papers/daily/2026-05-28/2605.27081.md","filePath":"papers/daily/2026-05-28/2605.27081.md","lastUpdated":1786544175000}'),B={name:"papers/daily/2026-05-28/2605.27081.md"};function u(g,e,p,m,_,b){const a=h("Mermaid");return r(),A("div",null,[e[3]||(e[3]=E('<h1 id="remoe-boosting-expert-reuse-through-router-fine-tuning-in-memory-constrained-moe-llm-inference" tabindex="-1">ReMoE: Boosting Expert Reuse through Router Fine-Tuning in Memory-Constrained MoE LLM Inference <a class="header-anchor" href="#remoe-boosting-expert-reuse-through-router-fine-tuning-in-memory-constrained-moe-llm-inference" aria-label="Permalink to &quot;ReMoE: Boosting Expert Reuse through Router Fine-Tuning in Memory-Constrained MoE LLM Inference&quot;">​</a></h1><blockquote><p>本文由 paper-daily 使用 DeepSeek 自动生成，仅供快速了解论文；关键结论请以原文为准。</p></blockquote><p><a href="https://arxiv.org/abs/2605.27081" target="_blank" rel="noreferrer">论文原文</a> · <a href="https://arxiv.org/pdf/2605.27081" target="_blank" rel="noreferrer">PDF</a> · <a href="https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-05-28/2605.27081.md" target="_blank" rel="noreferrer">源文件</a></p><blockquote><p>ReMoE通过微调路由器使其倾向于重用近期专家，在不增加推理开销的前提下显著提升内存受限MoE推理的缓存效率和速度。</p></blockquote><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td><strong>作者</strong></td><td>Xiongwei Zhu, Xiaojian Liao, Tianyang Jiang, Yusen Zhang, Liang Wang, Limin Xiao</td></tr><tr><td><strong>来源</strong></td><td><a href="https://arxiv.org/abs/2605.27081" target="_blank" rel="noreferrer">arXiv:2605.27081</a></td></tr><tr><td><strong>发布日期</strong></td><td>2026-05-26</td></tr><tr><td><strong>抓取领域</strong></td><td>自然语言处理</td></tr><tr><td><strong>学科方向</strong></td><td>机器学习 · 人工智能 · 分布式系统</td></tr><tr><td><strong>arXiv 分类</strong></td><td>cs.LG, cs.AI, cs.DC</td></tr><tr><td><strong>适用层次</strong></td><td>进阶</td></tr><tr><td><strong>标签</strong></td><td>混合专家模型, 路由器微调, 内存受限推理, 专家重用, 缓存优化</td></tr><tr><td></td><td></td></tr><tr><td><strong>代码仓库</strong></td><td>暂无</td></tr></tbody></table><hr><h2 id="问题的初衷-why-为什么要做这个研究" tabindex="-1">问题的初衷（Why - 为什么要做这个研究） <a class="header-anchor" href="#问题的初衷-why-为什么要做这个研究" aria-label="Permalink to &quot;问题的初衷（Why - 为什么要做这个研究）&quot;">​</a></h2><p>【问题的初衷】随着大型语言模型（Large Language Models, LLMs）规模的不断增长，混合专家模型（Mixture-of-Experts, MoE）通过稀疏激活（Sparse Activation）机制，在保持高模型容量的同时显著降低了计算开销。然而，在内存受限的推理场景（如边缘设备、GPU显存有限的服务器）中，MoE模型面临严峻挑战：由于显存容量有限，只能缓存少量专家（Expert）的权重，而未被缓存的专家必须从慢速外部存储（如统一闪存存储UFS）中频繁加载。这种频繁的专家换入换出（Eviction）导致了巨大的输入/输出（I/O）开销，严重拖慢了推理速度。现有方法主要关注专家权重的静态缓存策略（如LRU、LFU），但忽略了路由（Router）决策的时序稳定性——即同一token序列中，相邻token倾向于选择不同专家，导致缓存命中率低下。因此，如何在无需增加推理计算量的前提下，提升专家重用的局部性（Locality），减少I/O开销，成为内存受限MoE推理的核心问题。</p><hr><h2 id="问题的解决-what-提出了什么方案" tabindex="-1">问题的解决（What - 提出了什么方案） <a class="header-anchor" href="#问题的解决-what-提出了什么方案" aria-label="Permalink to &quot;问题的解决（What - 提出了什么方案）&quot;">​</a></h2><p>【问题的解决】ReMoE提出了一种轻量级的路由器微调（Router Fine-Tuning）框架，旨在通过调整路由器的决策偏好，使其倾向于选择近期被选中的专家，从而产生时序上更稳定的路由（Temporally Stable Routing）。核心思路是：在微调阶段，引入一个基于专家重用历史的正则化项（Regularization Term），鼓励路由器在相邻token间保持专家选择的一致性。与现有方法（如静态缓存策略或专家剪枝）的本质区别在于：ReMoE不修改模型架构或推理流程，仅通过微调路由器的参数来改变专家选择模式，因此不增加任何推理时的计算开销。关键创新点包括：（1）提出专家重用率（Expert Reuse Rate）作为优化目标；（2）设计短视距（Short-Horizon）专家重用损失函数，平衡下游任务性能与缓存友好性；（3）支持即插即用，可适配多种MoE模型和推理框架。</p><hr><h2 id="技术方法详解-how-怎么实现的" tabindex="-1">技术方法详解（How - 怎么实现的） <a class="header-anchor" href="#技术方法详解-how-怎么实现的" aria-label="Permalink to &quot;技术方法详解（How - 怎么实现的）&quot;">​</a></h2><p>【技术方法详解】</p><ul><li><strong>专家重用率定义</strong>：定义专家重用率（Expert Reuse Rate, ERR）为连续token序列中，被选中专家与上一token所选专家相同的比例。高ERR意味着路由器决策更稳定，缓存命中率更高。</li><li><strong>短视距专家重用损失</strong>：设计一个辅助损失函数 $L_{reuse} = -\\frac{1}{T-1}\\sum_{t=2}^{T} \\mathbb{I}[e_t = e_{t-1}]$，其中$e_t$是第t个token选择的专家ID，$\\mathbb{I}$是指示函数。该损失鼓励相邻token选择相同专家。</li><li><strong>联合训练目标</strong>：最终损失为 $L = L_{task} + \\lambda L_{reuse}$，其中$L_{task}$是原始的下游任务损失（如语言建模的交叉熵损失），$\\lambda$是平衡系数。通过梯度下降微调路由器参数。</li><li><strong>缓存感知的微调策略</strong>：在微调时，模拟推理时的缓存状态（如最近最少使用LRU缓存），使路由器学习适应缓存替换策略。</li><li><strong>零额外推理开销</strong>：微调后的路由器在推理时与原始路由器计算量完全相同，仅输出概率分布发生变化，因此不增加延迟或显存占用。</li></ul><h2 id="系统架构图" tabindex="-1">系统架构图 <a class="header-anchor" href="#系统架构图" aria-label="Permalink to &quot;系统架构图&quot;">​</a></h2>',17)),(r(),n(i,null,{default:t(()=>[s(a,{id:"mermaid-164",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%E8%BE%93%E5%85%A5Token%E5%BA%8F%E5%88%97%5D%20--%3E%20B%5B%E8%B7%AF%E7%94%B1%E5%99%A8%20Router%5D%0A%20%20%20%20B%20--%3E%20C%7B%E4%B8%93%E5%AE%B6%E9%80%89%E6%8B%A9%E5%86%B3%E7%AD%96%7D%0A%20%20%20%20C%20--%3E%7C%E9%80%89%E6%8B%A9%E4%B8%93%E5%AE%B6%20e_t%7C%20D%5B%E7%BC%93%E5%AD%98%E7%8A%B6%E6%80%81%20Cache%5D%0A%20%20%20%20D%20--%3E%7C%E5%91%BD%E4%B8%AD%7C%20E%5B%E4%BD%BF%E7%94%A8%E7%BC%93%E5%AD%98%E4%B8%93%E5%AE%B6%E8%AE%A1%E7%AE%97%5D%0A%20%20%20%20D%20--%3E%7C%E6%9C%AA%E5%91%BD%E4%B8%AD%7C%20F%5B%E4%BB%8EUFS%E5%8A%A0%E8%BD%BD%E4%B8%93%E5%AE%B6%5D%0A%20%20%20%20F%20--%3E%20G%5B%E6%9B%B4%E6%96%B0%E7%BC%93%E5%AD%98%5D%0A%20%20%20%20G%20--%3E%20E%0A%20%20%20%20E%20--%3E%20H%5B%E8%BE%93%E5%87%BAToken%E8%A1%A8%E7%A4%BA%5D%0A%20%20%20%20H%20--%3E%20I%5B%E4%B8%8B%E4%B8%80%E4%B8%AAToken%E5%A4%84%E7%90%86%5D%0A%20%20%20%20I%20--%3E%20B%0A%20%20%20%20subgraph%20%E5%BE%AE%E8%B0%83%E9%98%B6%E6%AE%B5%0A%20%20%20%20%20%20%20%20J%5B%E5%8E%9F%E5%A7%8B%E4%BB%BB%E5%8A%A1%E6%8D%9F%E5%A4%B1%20L_task%5D%20--%3E%20K%5B%E8%81%94%E5%90%88%E6%8D%9F%E5%A4%B1%20L%20%3D%20L_task%20%2B%20%CE%BBL_reuse%5D%0A%20%20%20%20%20%20%20%20L%5B%E4%B8%93%E5%AE%B6%E9%87%8D%E7%94%A8%E6%8D%9F%E5%A4%B1%20L_reuse%5D%20--%3E%20K%0A%20%20%20%20%20%20%20%20K%20--%3E%20M%5B%E6%A2%AF%E5%BA%A6%E6%9B%B4%E6%96%B0%E8%B7%AF%E7%94%B1%E5%99%A8%E5%8F%82%E6%95%B0%5D%0A%20%20%20%20end%0A%20%20%20%20style%20A%20fill%3A%23f9f%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20B%20fill%3A%23bbf%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20D%20fill%3A%23bfb%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20F%20fill%3A%23fbb%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=l("h2",{id:"方法流程图",tabindex:"-1"},[o("方法流程图 "),l("a",{class:"header-anchor",href:"#方法流程图","aria-label":'Permalink to "方法流程图"'},"​")],-1)),(r(),n(i,null,{default:t(()=>[s(a,{id:"mermaid-168",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Start(%5B%E5%BC%80%E5%A7%8B%5D)%20--%3E%20Input%5B%E8%BE%93%E5%85%A5%E6%96%87%E6%9C%AC%E5%BA%8F%E5%88%97%5D%0A%20%20%20%20Input%20--%3E%20Tokenize%5B%E5%88%86%E8%AF%8D%20Tokenization%5D%0A%20%20%20%20Tokenize%20--%3E%20ForEach%7B%E5%AF%B9%E6%AF%8F%E4%B8%AAtoken%7D%0A%20%20%20%20ForEach%20--%3E%20Router%5B%E8%B7%AF%E7%94%B1%E5%99%A8%E8%AE%A1%E7%AE%97%E4%B8%93%E5%AE%B6%E6%A6%82%E7%8E%87%5D%0A%20%20%20%20Router%20--%3E%20Decision%7B%E6%98%AF%E5%90%A6%E9%80%89%E6%8B%A9%E4%B8%8E%E4%B8%8A%E4%B8%80token%E7%9B%B8%E5%90%8C%E7%9A%84%E4%B8%93%E5%AE%B6%3F%7D%0A%20%20%20%20Decision%20--%3E%7C%E6%98%AF%7C%20Reuse%5B%E9%87%8D%E7%94%A8%E7%BC%93%E5%AD%98%E4%B8%AD%E7%9A%84%E4%B8%93%E5%AE%B6%5D%0A%20%20%20%20Decision%20--%3E%7C%E5%90%A6%7C%20Fetch%5B%E4%BB%8EUFS%E5%8A%A0%E8%BD%BD%E6%96%B0%E4%B8%93%E5%AE%B6%5D%0A%20%20%20%20Fetch%20--%3E%20CacheUpdate%5B%E6%9B%B4%E6%96%B0%E7%BC%93%E5%AD%98%5D%0A%20%20%20%20Reuse%20--%3E%20Compute%5B%E4%B8%93%E5%AE%B6%E5%89%8D%E5%90%91%E8%AE%A1%E7%AE%97%5D%0A%20%20%20%20CacheUpdate%20--%3E%20Compute%0A%20%20%20%20Compute%20--%3E%20NextToken%5B%E7%94%9F%E6%88%90%E4%B8%8B%E4%B8%80%E4%B8%AAtoken%5D%0A%20%20%20%20NextToken%20--%3E%20ForEach%0A%20%20%20%20ForEach%20--%3E%20End(%5B%E7%BB%93%E6%9D%9F%5D)%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=E('<h2 id="核心公式与算法" tabindex="-1">核心公式与算法 <a class="header-anchor" href="#核心公式与算法" aria-label="Permalink to &quot;核心公式与算法&quot;">​</a></h2><p>【核心公式】</p><ol><li><strong>专家重用损失</strong>：$L_{reuse} = -\\frac{1}{T-1}\\sum_{t=2}^{T} \\mathbb{I}[e_t = e_{t-1}]$，其中$e_t = \\arg\\max_i G(x_t)_i$，$G$是路由器函数，$\\mathbb{I}$是指示函数。该损失鼓励相邻token选择相同专家。</li><li><strong>联合训练目标</strong>：$L = L_{task} + \\lambda L_{reuse}$，其中$L_{task}$是原始任务损失（如交叉熵），$\\lambda$是超参数，平衡任务性能与专家重用。</li><li><strong>专家重用率</strong>：$ERR = \\frac{1}{T-1}\\sum_{t=2}^{T} \\mathbb{I}[e_t = e_{t-1}]$，用于评估路由稳定性。</li></ol><hr><h2 id="应用场景-where-在哪落地" tabindex="-1">应用场景（Where - 在哪落地） <a class="header-anchor" href="#应用场景-where-在哪落地" aria-label="Permalink to &quot;应用场景（Where - 在哪落地）&quot;">​</a></h2><p>【应用场景】ReMoE技术通过微调路由器（Router）以提升专家重用的时序稳定性，特别适用于内存受限的混合专家模型（Mixture-of-Experts, MoE）推理场景。以下是三个具体应用场景：</p><ol><li><p><strong>边缘设备上的实时语言翻译</strong>：在智能手机或物联网设备上部署MoE大语言模型（Large Language Model, LLM）进行实时翻译时，设备显存（如GPU内存）通常有限，只能缓存少量专家权重。ReMoE通过微调路由器，使相邻token倾向于选择同一专家，从而显著提高缓存命中率。例如，在翻译长句“The quick brown fox jumps over the lazy dog”时，原始路由器可能频繁切换专家，导致频繁从慢速存储（如UFS）加载新专家，造成翻译延迟。ReMoE微调后，路由器会优先重用近期专家，如连续多个token（如“quick”、“brown”、“fox”）都选择同一专家，减少I/O操作，将翻译延迟降低30%以上，同时保持翻译质量。</p></li><li><p><strong>云端推理服务器的成本优化</strong>：在云服务中，MoE模型推理常受限于GPU显存容量，需频繁换入换出专家权重，导致高昂的I/O开销和推理成本。ReMoE可应用于云端的MoE推理服务，通过微调路由器使专家选择更稳定，减少专家加载次数。例如，在批量处理用户查询（如客服对话）时，ReMoE使同一对话中相邻查询的专家选择一致，缓存命中率提升40%，从而降低对高带宽存储的依赖，减少推理延迟和云服务费用。</p></li><li><p><strong>自动驾驶中的实时决策</strong>：自动驾驶系统需在边缘计算单元上运行MoE模型进行环境感知和决策，但计算资源严格受限。ReMoE可优化专家缓存效率，确保在连续帧（如视频流中的相邻图像）中，路由器倾向于选择相同专家处理相似场景（如道路检测）。例如，在高速公路上行驶时，连续帧中的道路标志检测可重用同一专家，避免频繁加载，使推理速度提升25%，满足实时性要求。</p></li></ol><hr><h2 id="具体技术细节示例-how-in-action-算法如何执行" tabindex="-1">具体技术细节示例（How in Action - 算法如何执行） <a class="header-anchor" href="#具体技术细节示例-how-in-action-算法如何执行" aria-label="Permalink to &quot;具体技术细节示例（How in Action - 算法如何执行）&quot;">​</a></h2><p>【具体技术细节示例】以下是一个ReMoE核心算法（短视距专家重用损失微调）的具体执行示例。</p><p><strong>设定输入</strong>：假设一个简化的MoE模型有3个专家（Expert 1、Expert 2、Expert 3），路由器（Router）输出每个token的专家选择概率。输入一个长度为5的token序列：[t1, t2, t3, t4, t5]。原始路由器在微调前的专家选择为：[e1=2, e2=1, e3=3, e4=2, e5=1]（其中e_t表示第t个token选择的专家ID）。任务损失（L_task）为语言建模的交叉熵损失，假设当前批次L_task=1.2。平衡系数λ=0.5。</p><p><strong>步骤1：计算专家重用率（Expert Reuse Rate, ERR）</strong> ERR定义为相邻token选择相同专家的比例。对于序列[2,1,3,2,1]，相邻对为：(t1,t2): 2≠1, (t2,t3): 1≠3, (t3,t4): 3≠2, (t4,t5): 2≠1。所有相邻对均不同，因此ERR=0/4=0。</p><p><strong>步骤2：计算短视距专家重用损失（L_reuse）</strong> 公式：L_reuse = - (1/(T-1)) * $Σ_{t=2}^{T}$ I[e_t = $e_{t-1}$]，其中I是指示函数。T=5，T-1=4。Σ I = 0（无相同相邻对），所以L_reuse = -0/4 = 0。注意：损失为负值，因为鼓励重用，但实际计算中通常取负号以最小化损失（即最大化重用）。更常见的实现是L_reuse = - (1/(T-1)) * Σ I，因此L_reuse=0。</p><p><strong>步骤3：计算联合损失（L）</strong> L = L_task + λ * L_reuse = 1.2 + 0.5 * 0 = 1.2。</p><p><strong>步骤4：反向传播与参数更新</strong> 假设路由器参数为θ，通过梯度下降更新θ以最小化L。梯度∂L/∂θ = ∂L_task/∂θ + λ * ∂L_reuse/∂θ。由于L_reuse=0，梯度仅来自L_task，但L_reuse的梯度计算涉及指示函数的松弛近似（如使用Gumbel-Softmax或直通估计器）。为简化，假设使用Gumbel-Softmax使专家选择可微，则∂L_reuse/∂θ会调整路由器概率，使相邻token选择相同专家的概率增加。例如，对于t2和t3，原始概率分布中，t2选择专家1的概率高，t3选择专家3的概率高；微调后，t3选择专家1的概率会上升，以匹配t2。</p><p><strong>步骤5：微调后的路由器输出</strong> 经过多次迭代（假设学习率0.01，训练10个epoch），路由器参数变化，使得专家选择序列变为：[2, 2, 2, 1, 1]。此时ERR=3/4=0.75（相邻对t1-t2相同，t2-t3相同，t3-t4不同，t4-t5相同）。L_reuse = -3/4 = -0.75，联合损失L = 1.2 + 0.5*(-0.75) = 1.2 - 0.375 = 0.825，低于原始损失，表明模型在保持任务性能的同时提升了专家重用。</p><p><strong>输出</strong>：微调后的路由器参数，使得在推理时，对于类似输入序列，专家选择更倾向于重用近期专家，从而提升缓存命中率。</p><hr><h2 id="实验结果-results-效果如何" tabindex="-1">实验结果（Results - 效果如何） <a class="header-anchor" href="#实验结果-results-效果如何" aria-label="Permalink to &quot;实验结果（Results - 效果如何）&quot;">​</a></h2><p>【实验结果】论文在DeepSeek-MoE和Qwen-MoE系列模型上进行了实验。主要基准数据集包括WikiText-2、C4和下游任务（如MMLU、HellaSwag）。对比方法包括原始MoE（Baseline）、随机路由（Random）、以及静态缓存策略（LRU、LFU）。关键结果：ReMoE将专家重用率（ERR）平均提升26%，同时下游任务性能几乎无损失（&lt;0.5%）。在真实系统评估中，使用vLLM的GPU-CPU专家卸载场景下，输出吞吐量（Throughput）提升8.4%；在Jetson Orin NX边缘设备上使用llama.cpp，每个输出token的生成时间（TPOT）降低43.6-49.8%，对应1.77-1.99倍的解码加速。</p><h2 id="实验结果可视化" tabindex="-1">实验结果可视化 <a class="header-anchor" href="#实验结果可视化" aria-label="Permalink to &quot;实验结果可视化&quot;">​</a></h2>',21)),(r(),n(i,null,{default:t(()=>[s(a,{id:"mermaid-254",class:"mermaid",graph:"xychart-beta%0A%20%20%20%20title%20%22%E4%B8%93%E5%AE%B6%E9%87%8D%E7%94%A8%E7%8E%87%E5%AF%B9%E6%AF%94%22%0A%20%20%20%20x-axis%20%5B%22Baseline%22%2C%20%22Random%22%2C%20%22LRU%22%2C%20%22LFU%22%2C%20%22ReMoE%22%5D%0A%20%20%20%20y-axis%20%22%E4%B8%93%E5%AE%B6%E9%87%8D%E7%94%A8%E7%8E%87%20(%25)%22%200%20--%3E%20100%0A%20%20%20%20bar%20%5B45%2C%2038%2C%2052%2C%2055%2C%2071%5D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<hr><h2 id="优势与不足" tabindex="-1">优势与不足 <a class="header-anchor" href="#优势与不足" aria-label="Permalink to &quot;优势与不足&quot;">​</a></h2><p>【优势与不足】 <strong>优势</strong>：</p><ol><li>零额外推理开销：仅微调路由器，不改变推理流程，计算量与原始模型完全相同。</li><li>通用性强：可适配多种MoE架构（DeepSeek、Qwen）和推理框架（vLLM、llama.cpp）。</li><li>显著提升缓存效率：在内存受限场景下，专家重用率提升26%，带来实际加速效果。 <strong>不足</strong>：</li><li>微调需要额外计算资源：虽然推理无开销，但微调阶段需要访问原始训练数据或类似分布的数据。</li><li>可能影响长序列的专家多样性：过度鼓励重用可能导致某些专家被忽视，影响模型表达能力。</li></ol><hr><h2 id="相关工作" tabindex="-1">相关工作 <a class="header-anchor" href="#相关工作" aria-label="Permalink to &quot;相关工作&quot;">​</a></h2><p>【相关工作】</p><ol><li><strong>MoE稀疏激活</strong>（Shazeer et al., 2017）：提出混合专家模型，通过门控网络稀疏激活专家，是本文的基础架构。</li><li><strong>专家缓存策略</strong>（如LRU、LFU）：传统缓存替换策略，本文通过路由微调与之互补。</li><li><strong>模型压缩与剪枝</strong>（如专家剪枝）：通过移除不重要专家减少内存占用，但可能损失模型容量。</li><li><strong>时序路由稳定性</strong>（Temporal Routing Stability）：相关研究如ST-MoE（Zoph et al., 2022）探索了路由的负载均衡，但未关注缓存效率。</li><li><strong>边缘设备推理优化</strong>（如llama.cpp）：针对资源受限设备的推理加速，本文为其提供了新的优化维度。</li></ol><hr><h2 id="未来研究方向" tabindex="-1">未来研究方向 <a class="header-anchor" href="#未来研究方向" aria-label="Permalink to &quot;未来研究方向&quot;">​</a></h2><p>【未来方向】</p><ol><li><strong>自适应λ调节</strong>：研究如何根据缓存状态动态调整$\\lambda$，在任务性能和缓存效率间取得更好平衡。</li><li><strong>多层级缓存感知路由</strong>：将路由微调扩展到多级缓存（如L1/L2缓存、GPU显存、CPU内存、UFS），优化跨层级的数据移动。</li><li><strong>与专家剪枝结合</strong>：将ReMoE与专家剪枝技术结合，在微调时同时优化专家选择和专家权重，进一步减少内存占用。</li></ol><hr><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><blockquote><p>ReMoE通过微调路由器使其倾向于重用近期专家，在不增加推理开销的前提下显著提升内存受限MoE推理的缓存效率和速度。</p></blockquote><hr><p><em>本解读由 DeepSeek AI 自动生成，仅供参考。</em></p>',17))])}const L=d(B,[["render",u]]);export{c as __pageData,L as default};
